INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('76f69795-93e1-49b9-976a-681235984e52', 'Common Area Maintenance Charges', '2', 'APARTADO 19', 'CUOTA DE MANTENIMIENTO', E'- Local 114:\n  - Rent: $32,285.48\n  - Additional 15% VAT: $215,236.58\n\n- Local 124:\n  - Rent: $1,761.75\n  - Additional 10% VAT: $17,617.50\n\n- Total maintenance cost: $34,047.23\n  - This amount should be paid monthly along with the rent.', E'Local 114: $32,285.48 (Treinta y dos mil doscientos ochenta y cinco pesos 48/100 M.N.) más IVA equivalente al 15% del monto de la renta que asciende a $215,236.58 (Doscientos quince mil doscientos treinta y seis pesos 58/100 M.N.) \nLocal 124: $1,761.75 (Mil setecientos sesenta y un pesos 75/100 M.N.) más IVA equivalente al 10% del monto de la renta que asciende a la cantidad de $$17,617.50 (Diecisiete mil seiscientos diecisiete pesos 50/100 M.N). \n\nTotal de mantenimiento. $34,047.23 (Treinta más IVA mensuales, cantidad que deberá ser pagada de manera simultánea al pago de la Renta.');
