INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('2aa09ac3-301d-4753-969a-040003c5f0b0', 'Late Fees', '14', '16', 'INTERESES MORATORIOS', E'- The tenant must make all payments on time as agreed in the contract.\n- If a payment is late, a late fee interest of 2% per month will be charged.\n- This interest applies to the total unpaid amount.\n- The late fee is charged if the payment is more than 60 days overdue.\n- The interest is calculated monthly or for any part of a month until the payment is made.', E'La Arrendataria se obliga a cumplir con todas y cada una de las obligaciones de pago pactadas en el presente contrato, precisamente en las fechas o términos convenidos, y acepta cubrir en el caso de mora de cualquier pago los intereses moratorios que se calcularán como sigue:\nLa tasa de intereses moratorios será del 2% (dos por ciento) mensual. Esta tasa se aplicará sobre el importe total del adeudo no cubierto puntualmente. Dicho interés moratorio será exigible cuando la Arrendataria se retrase en un pago por más de 60 (sesenta) días de la fecha en que debió hacerlo. Este interés mensual se calculará cada mes o fracción de mes, mientras dure la mora, y por todo el tiempo transcurrido desde la fecha inicial en que debió hacerse el pago y hasta la liquidación del mismo.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('2aa09ac3-301d-4753-969a-040003c5f0b0', 'Common Area Maintenance Charges', '8', '9 A)', 'GASTOS DE ADMINISTRACIÓN Y MANTENIMIENTO', E'- The monthly rent includes management and maintenance expenses.\n- The landlord must use these funds to maintain, repair, and replace parts of the shopping center.\n- This includes common areas, cleaning, security, lighting, and the overall appearance of the shopping center.\n- The goal is to keep everything in optimal working condition.', 'Las Partes acuerda que los gastos de administración y mantenimiento se encuentran incluidos en el monto de la Renta Mensual. La Arrendadora tendrá la obligación de usar los fondos para mantener, reparar y reemplazar el Centro Comercial, áreas comunes, limpieza, seguridad, iluminación, imagen del Centro Comercial y los elementos del mismo para mantenerlos en óptimas condiciones de funcionamiento.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('2aa09ac3-301d-4753-969a-040003c5f0b0', 'Incremento de Renta', '6', '5', 'AJUSTE DE LA RENTA', E'- The Monthly Rent will increase every 12 months.\n- The increase starts from the opening date or the end of the grace period, whichever comes first.\n- The increase is based on the change in the National Consumer Price Index (INPC).\n- The INPC is published monthly by the National Institute of Statistics and Geography (INEGI).\n- The comparison is made between the INPC two months before the lease starts or the last rent adjustment and the INPC two months before the new adjustment.\n- If the increase percentage is more than 4%, the maximum increase will be capped at 4%.', E'Las Partes convienen que la Renta Mensual será incrementada cada 12 (doce) meses, contado a partir de la fecha de apertura o el término del periodo de gracia, lo que ocurra primero, se ajustará el importe de la Renta Mensual, incrementándose de acuerdo con la siguiente mecánica:\n\nSe tomará como base el porcentaje que haya variado el índice Nacional de Precios al Consumidor (INPC), que publica mensualmente el Instituto Nacional de Estadística y Geografía (INEGI), comparando el correspondiente al de dos meses inmediatos anteriores al mes de inicio del arrendamiento o al del último ajuste de renta y el correspondiente al de dos meses inmediatos anteriores al mes en que deba efectuarse el ajuste, en el entendido que si el porcentaje de incremento es mayor al 4% (cuatro por ciento) éste será el porcentaje máximo de incremento de la Renta Mensual.');
