ils":"No","lease_is_silent":"No","rtr_enabled":1,"grid_id":61615,"grid_name":"Malecón Las Américas, Cancún","grid_full_address":"06 01 Avenida Bonampak, A-09, Benito Juárez, Quintana Roo 77500","map_addr_1":"06 01 Avenida Bonampak","map_addr_2":"A-09","map_city_state_zip":"Benito Juárez, Quintana Roo 77500","grid_brand":"Planet Fitness","is_next_percent_rent_payment":"No","location_created_at":"2026-01-05 15:19:16","active_lease_count_over_time":55370,"location_count_over_time":61615,"remaining_rent_liability_over_time":55370,"base_rent_current_month":"500000.0000","cam_current_month":"50000.0000","base_rent_next_month":"500000.0000","cam_next_month":"50000.0000","base_rent_per_square_meter":"3853.56","cam_per_square_meter":"385.36","base_rent_per_year":"6000000.0000","cam_per_year":"600000.0000"}'::jsonb);
