INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('2a2ca8bf-baee-48ce-8bf4-6b73140a7d7b', 'Lease note', 'La versión del contrato no es la final', 'America Gonzalez', NULL);
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('2a2ca8bf-baee-48ce-8bf4-6b73140a7d7b', 'Late Fees', '4', '1', 'INTERESES MORATORIOS', E'- If the tenant is late in paying rent, maintenance fees, or any other owed payments, they must pay late interest.\n- The interest is calculated by multiplying the owed amount by the current Interbank Equilibrium Interest Rate (TIIE) set by the Bank of Mexico, then multiplying by 3, and dividing by 360.\n- This result is then multiplied by the number of days the payment is late.\n- The tenant must pay this interest for the entire period of delay.\n- The final amount, expressed in pesos, is the late interest the tenant owes the landlord.', 'Significa aplicarse diariamente, tanto para el caso de retraso en el pago de la Renta como de retraso en el pago de la Cuota de Mantenimiento o cualquier pago que adeude el Arrendatario al Arrendador, serán el equivalente de multiplicar el importe de la cantidad adeudada por la Tasa de Interés Interbancaria de Equilibrio (TIIE) vigente que al momento del incumplimiento determine el Banco. de México por 3 (tres) entre 360 (trescientos sesenta), y el resultado se multiplicará por el número de días naturales que dure el incumplimiento respectivo, quedando obligado el Arrendatario a pagar intereses por todo el tiempo que dure la mora. Este último resultado se expresará en pesos y será el monto que por concepto de Intereses Moratorios deba de pagar el Arrendatario al Arrendador.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('2a2ca8bf-baee-48ce-8bf4-6b73140a7d7b', 'Incremento de Renta', '10', '7', 'INCREMENTOS', E'- The fixed rent will increase annually starting from the second year after the rent start date.\n- The increase will match the percentage change in the National Consumer Price Index (INPC) or its replacement from the previous calendar year.\n- If the INPC change cannot be determined, the increase will be based on the INPC from the month before the scheduled increase.\n- Once the INPC is known, any necessary adjustments will be made, and the tenant must pay the landlord any differences.\n- The tenant is responsible for all maintenance and service expenses, including water, electricity, gas, phone, and any other related costs.', 'Las Partes acuerdan que la Renta Fija se incrementará anualmente, a partir del inicio del segundo año siguiente a la Fecha de Inicio de la Renta, aplicando el mismo porcentaje de variación que haya sufrido el INPC, O aquel que lo sustituya, durante el año calendario inmediatamente anterior. Para ese fin, se determinará el incremento en un porcentaje igual al porcentaje de incremento que haya registrado durante los 12 (doce) meses calendarios inmediatos anteriores del INPC. Asimismo, las Partes acuerdan que en caso de que no sea posible determinar la variación en el INPC correspondiente, esta se calculará considerando el INPC del mes inmediato anterior a aquel en el cual debiera realizarse el incremento conforme a la presente Cláusula, en el entendido que una vez conocido el INPC, se deberá realizar la actualización correspondiente y el Arrendatario deberá pagar al Arrendador las diferencias correspondientes surgidas de dicha actualización. Octava. Mantenimiento y Gastos. Las Partes acuerdan que todos los gastos de mantenimiento y servicios del Bien Arrendado corren por cuenta exclusiva del Arrendatario incluyendo, sin limitación, todos los gastos por consumo de agua, suministro de energía eléctrica, gas, teléfonos, y cualquier otro que pueda surgir por este concepto, o bien, que contrate por su cuenta.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('2a2ca8bf-baee-48ce-8bf4-6b73140a7d7b', 'Common Area Maintenance Charges', '3', '1', 'CUOTA DE MANTENIMIENTO', E'- El arrendatario es responsable de todos los gastos de mantenimiento y servicios del bien arrendado, como agua, electricidad, gas, y teléfono.\n- El arrendatario debe pagar al arrendador una Cuota de Mantenimiento más IVA dentro de los primeros 5 días de cada mes.\n- La Cuota de Mantenimiento cubre gastos de mantenimiento de áreas comunes, administración y publicidad del centro comercial, y otros gastos necesarios.\n- El pago de la Cuota de Mantenimiento comienza desde la Fecha de Inicio de Renta.', E'Significa la cantidad equivalente al 10 % (diez por ciento) de la Renta Fija. \nLas Partes acuerdan que todos los gastos de mantenimiento y servicios del Bien Arrendado corren por cuenta exclusiva del Arrendatario incluyendo, sin limitación, todos los gastos por consumo de agua, suministro de energía eléctrica, gas, teléfonos, y cualquier otro que pueda surgir por este concepto, o bien, que contrate por su cuenta. Asimismo, el Arrendatario deberá pagar al Arrendador, dentro de los 5 (cinco) primeros días naturales de cada mes, la Cuota de Mantenimiento más IVA, para cubrir los gastos de mantenimiento de áreas comunes, gastos de administración del Centro Comercial, gastos de publicidad del Centro Comercial, y cualesquiera otros gastos que sean necesarios para el debido mantenimiento del Centro Comercial. La Cuota de Mantenimiento se comenzará a pagar a partir de la Fecha de Inicio de Renta.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('2a2ca8bf-baee-48ce-8bf4-6b73140a7d7b', 'Percentage Rent', '5', '1', 'RENTA VARIABLE', E'- The tenant must pay 10% of the Net Sales for a calendar month, plus VAT.\n- The tenant must send a report of the previous month''s Net Sales to the landlord within the first 5 days of each month.\n- If the Variable Rent (based on sales) is higher than the Fixed Rent, the tenant must pay the difference by the 15th of the following month.\n- Delays in sending the sales report do not change the payment deadlines for Variable Rent.\n- Failing to send the sales report on time can lead to the termination of the contract without legal proceedings and without liability for the landlord.', E'Significa el 10% (diez por ciento) de las Ventas Netas de un mes calendario, más el IVA.\nEl Arrendatario deberá enviar al Arrendador, dentro de los 5 (cinco) primeros días naturales de cada mes, el reporte que refleje las Ventas Netas del Bien Arrendado durante el mes inmediato anterior. En caso que dicho reporte refleje que la Renta Variable resulta mayor la que Renta Fija, el Arrendatario deberá pagar al Arrendador, el diferencial que exista entre la Renta Fija y la Renta Variable, a más tardar el día 15 (quince) del mes inmediato siguiente al mes de que se trate. El retraso del Arrendatario en el envío del reporte de las Ventas Netas, no modificará los plazos establecidos para el pago de la Renta Variable, en caso que esta se genere, asimismo, el incumplimiento por parte del Arrendatario en el envío del reporte de las Ventas Netas dentro del plazo señalado en el párrafo anterior, será causa de rescisión del presente Contrato, sin necesidad de declaración judicial y sin responsabilidad alguna para el Arrendador.');
